module maze_escape(\n    input clk,\n    input rst_n,\n    input start,\n    input [127:0] grid_data,\n    output reg [5:0] result,\n    output reg done\n);\n\n    localparam [2:0] IDLE = 3'd0;\n    localparam [2:0] FIRE_BFS_INIT = 3'd1;\n    localparam [2:0] FIRE_BFS_PROCESS = 3'd2;\n    localparam [2:0] FIRE_BFS_CHECK = 3'd3;\n    localparam [2:0] JOE_BFS_INIT = 3'd4;\n    localparam [2:0] JOE_BFS_PROCESS = 3'd5;\n    localparam [2:0] JOE_BFS_CHECK = 3'd6;\n    localparam [2:0] DONE = 3'd7;\n\n    reg [2:0] state, next_state;\n    reg [1:0] grid [0:7][0:7];\n    reg [6:0] fire_time [0:7][0:7];\n    reg visited [0:7][0:7];\n\n    reg [5:0] fire_queue [0:63];\n    reg [5:0] fire_q_wr, fire_q_rd;\n    wire fire_q_empty = (fire_q_wr == fire_q_rd);\n    wire fire_q_full = ((fire_q_wr + 6'd1) == fire_q_rd) || (fire_q_wr == 6'd63 && fire_q_rd == 6'd0);\n\n    reg [11:0] joe_queue [0:63];\n    reg [5:0] joe_q_wr, joe_q_rd;\n    wire joe_q_empty = (joe_q_wr == joe_q_rd);\n    wire joe_q_full = ((joe_q_wr + 6'd1) == joe_q_rd) || (joe_q_wr == 6'd63 && joe_q_rd == 6'd0);\n\n    reg [2:0] cur_r, next_r;\n    reg [2:0] cur_c, next_c;\n    reg [5:0] cur_time, next_time;\n    reg [1:0] dir, next_dir;\n\n    wire [2:0] nr = (dir == 2'd0) ? cur_r - 3'd1 : (dir == 2'd1) ? cur_r + 3'd1 : cur_r;\n    wire [2:0] nc = (dir == 2'd2) ? cur_c - 3'd1 : (dir == 2'd3) ? cur_c + 3'd1 : cur_c;\n    wire in_bounds = (nr < 3'd7) && (nc < 3'd7);\n\n    integer i, j;\n    always @(posedge clk or negedge rst_n) begin\n        if (!rst_n) begin\n            done <= 1'b0;\n            result <= 6'b111111;\n            state <= IDLE;\n            fire_q_wr <= 6'd0;\n            fire_q_rd <= 6'd0;\n            joe_q_wr <= 6'd0;\n            joe_q_rd <= 6'd0;\n            /* Array initialization */\n            for (i = 0; i < 8; i = i + 1) begin\n                for (j = 0; j < 8; j = j + 1) begin\n                    grid[i][j] <= 2'd0;\n                    fire_time[i][j] <= 7'd127;\n                    visited[i][j] <= 1'b0;\n                end\n            end\n            for (i = 0; i < 64; i = i + 1) begin\n                fire_queue[i] <= 6'd0;\n                joe_queue[i] <= 12'd0;\n            end\n            cur_r <= 3'd0;\n            cur_c <= 3'd0;\n            cur_time <= 6'd0;\n            dir <= 2'd0;\n        end else begin\n            state <= next_state;\n            cur_r <= next_r;\n            cur_c <= next_c;\n            cur_time <= next_time;\n            dir <= next_dir;\n\n            case (state)\n                IDLE: begin\n                    done <= 1'b0;\n                    if (start) begin\n                        for (i = 0; i < 8; i = i + 1) begin\n                            for (j = 0; j < 8; j = j + 1) begin\n                                grid[i][j] <= grid_data[(i*16 + j*2) +: 2];\n                            end\n                        end\n                        next_state <= FIRE_BFS_INIT;\n                    end\n                end\n\n                FIRE_BFS_INIT: begin\n                    for (i = 0; i < 8; i = i + 1) begin\n                        for (j = 0; j < 8; j = j + 1) begin\n                            fire_time[i][j] <= 7'd127;\n                            visited[i][j] <= 1'b0;\n                            if (grid[i][j] == 2'b11 && !fire_q_full) begin\n                                fire_queue[fire_q_wr] <= {i, j};\n                                fire_q_wr <= fire_q_wr + 6'd1;\n                                fire_time[i][j] <= 7'd0;\n                            end\n                        end\n                    end\n                    next_state <= FIRE_BFS_PROCESS;\n                end\n\n                FIRE_BFS_PROCESS: begin\n                    if (!fire_q_empty) begin\n                        {next_r, next_c} <= fire_queue[fire_q_rd];\n                        fire_q_rd <= fire_q_rd + 6'd1;\n                        next_dir <= 2'd0;\n                        next_state <= FIRE_BFS_CHECK;\n                    end else begin\n                        next_state <= JOE_BFS_INIT;\n                    end\n                end\n\n                FIRE_BFS_CHECK: begin\n                    if (in_bounds && grid[nr][nc] != 2'b00 && fire_time[nr][nc] == 7'd127) begin\n                        fire_time[nr][nc] <= fire_time[cur_r][cur_c] + 7'd1;\n                        if (!fire_q_full) begin\n                            fire_queue[fire_q_wr] <= {nr, nc};\n                            fire_q_wr <= fire_q_wr + 6'd1;\n                        end\n                    end\n                    if (dir < 2'd3) begin\n                        next_dir <= dir + 2'd1;\n                        next_state <= FIRE_BFS_CHECK;\n                    end else begin\n                        next_state <= FIRE_BFS_PROCESS;\n                    end\n                end\n\n                JOE_BFS_INIT: begin\n                    for (i = 0; i < 8; i = i + 1) begin\n                        for (j = 0; j < 8; j = j + 1) begin\n                            if (grid[i][j] == 2'b10 && !joe_q_full) begin\n                                joe_queue[joe_q_wr] <= {i, j, 6'd0};\n                                joe_q_wr <= joe_q_wr + 6'd1;\n                                visited[i][j] <= 1'b1;\n                            end\n                        end\n                    end\n                    next_state <= JOE_BFS_PROCESS;\n                end\n\n                JOE_BFS_PROCESS: begin\n                    if (!joe_q_empty) begin\n                        {next_r, next_c, next_time} <= joe_queue[joe_q_rd];\n                        joe_q_rd <= joe_q_rd + 6'd1;\n                        next_dir <= 2'd0;\n                        next_state <= JOE_BFS_CHECK;\n                    end else begin\n                        result <= 6'b111111;\n                        done <= 1'b1;\n                        next_state <= DONE;\n                    end\n                end\n\n                JOE_BFS_CHECK: begin\n                    if ((cur_r == 3'd0 || cur_r == 3'd7 || cur_c == 3'd0 || cur_c == 3'd7) && !done) begin\n                        result <= cur_time;\n                        done <= 1'b1;\n                        next_state <= DONE;\n                    end else begin\n                        if (in_bounds && grid[nr][nc] != 2'b00 && !visited[nr][nc] && \n                            ((fire_time[nr][nc] > (cur_time[6:0] + 7'd1)) || fire_time[nr][nc] == 7'd127)) begin\n                            if (!joe_q_full) begin\n                                joe_queue[joe_q_wr[5:0]] <= {nr, nc, cur_time + 6'd1};\n                                joe_q_wr <= joe_q_wr + 6'd1;\n                                visited[nr][nc] <= 1'b1;\n                            end\n                        end\n                        if (dir < 2'd3) begin\n                            next_dir <= dir + 2'd1;\n                            next_state <= JOE_BFS_CHECK;\n                        end else begin\n                            next_state <= JOE_BFS_PROCESS;\n                        end\n                    end\n                end\n\n                DONE: begin\n                    done <= 1'b1;\n                    next_state <= DONE;\n                end\n\n                default: begin\n                    next_state <= IDLE;\n                end\n            endcase\n        end\n    end\n\nendmodule